function getJson(key) {
    return fetch(API + key, { cache: 'no-store' }).then(function (r) { if (!r.ok) throw new Error(r.status); return r.json(); });
  }

function poll() {
    if (!pollAllowed()) return;
    if (sharedDemo || demo[cur]) {   // offline layout only
      if (cur === 'home') renderHome(demoHome(Number($('s-demoType').value)), true);
      else if (cur === 'version') renderVersion(DEMO.gpib, DEMO.rs232);
      else render[cur](DEMO[cur], true);
      return;
    }
    if (inflight) return;
    inflight = true;
    // only what the open tab shows: Test Result -> the ONE home JSON; a mode tab -> its engine; Version -> the two programs
    var need = cur === 'home' ? ['home'] : (cur === 'version' ? verKeys : [cur]);
    Promise.all(need.map(function (k) {
      return getJson(k).then(function (s) { return [k, s]; }, function () { return [k, null]; });
    })).then(function (res) {
      var snaps = {};
      res.forEach(function (r) { snaps[r[0]] = r[1]; });
      if (cur === 'home') { renderHome(snaps.home, snaps.home != null); if (snaps.home) applyBuildTabs(snaps.home); }
      else if (cur === 'version') renderVersion(snaps.gpib, snaps.rs232);
      else render[cur](snaps[cur], snaps[cur] != null);
    }).catch(function () {}).then(function () { inflight = false; });
  }

function post(key, cmd) {
    // AI(W906-TC-SHARED) 20261001 (St02-E): the Home demo (s-demo) never posts either
    if (demo[key] || sharedDemo) { console.log('[demo] ' + key + ': ' + cmd); return; }   // AI(W906-MOTB-TCVIS) 20261002: was (key === 'home' && sharedDemo) -- with the Home demo on, poll() draws DEMO data on every tab (:667) but the GPIB / RS232 clicks still went live
    // wb_serve's HTTP route hook sees no request body, so the command travels in the query (URL-encoded)
    fetch(API + key + '?cmd=' + encodeURIComponent(cmd), { method: 'POST' }).catch(function () {});
  }

function stateBadge(id, snap, ok) {
    var e = $(id);
    e.className = 'tcState ' + (!ok ? 'off' : (snap && snap.up ? 'up' : 'down'));
    e.textContent = !ok ? '離線（/api/testercomm 未接）' : (snap && snap.up ? '連線中' : ('已停止' + (snap && snap.closeReason ? '：' + snap.closeReason : '')));
  }

function applyPageTable(v){
  var t=null;
  try{ t=(typeof v==='string')?JSON.parse(v):v; }catch(e){ return; }
  if(!t || !t.rows || !t.rows.forEach) return;
  t.rows.forEach(function(r){
    if(!r || !r.id || !r.want || !r.wseq) return;
    if(PAGES_APPLIED[r.id]===r.wseq) return;
    PAGES_APPLIED[r.id]=r.wseq;
    if(!(r.id in WIN_STATE)) return;               // 這台沒建立這個視窗（absent）
    var st=WIN_STATE[r.id], on=(st==='open'||st==='minimized');
    if(r.want==='open' && !on){ console.info('[HT9xxx] ui.pages：C++ 開 '+r.id+'（'+(r.by||'')+'）'); openWin(r.id,true); }
    else if(r.want==='close' && on){ console.info('[HT9xxx] ui.pages：C++ 關 '+r.id+'（'+(r.by||'')+'）'); closeWin(r.id); }
  });
  if(!PAGES_CHECKED){
    PAGES_CHECKED=true;
    var shot={}, mine={}, cpp={}, miss=[];
    (window.SHOT_WINDOWS||[]).forEach(function(w){ shot[w.id]=true; });
    WINDOWS.forEach(function(w){ if(!shot[w.id]) mine[w.id]=true; });
    t.rows.forEach(function(r){ if(r && r.id && r.id.indexOf(':')<0) cpp[r.id]=true; });
    Object.keys(mine).forEach(function(id){ if(!cpp[id]) miss.push('網頁有、C++ 沒有：'+id); });
    Object.keys(cpp).forEach(function(id){ if(!mine[id]) miss.push('C++ 有、網頁沒有：'+id); });
    if(miss.length) console.warn('[HT9xxx] 頁面表不一致（C++ ui.pages 對 WINDOWS 表）：\n'+miss.join('\n'));
    window.HT_PAGES_MISMATCH=miss;
  }
}

